INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwfxkff0002xsv3zq7h7zq4', 'cmqwfwoqj0001xsv3l851r09m', 'アンソロピック「ミュトス5」を復活　米国のインフラ組織に再展開', 'https://www.watch.impress.co.jp/docs/news/2120572.html', '2026-06-27T02:32:57.000+00:00', 'https://www.watch.impress.co.jp/img/ipw/list/2120/572/an1.jpg', 'Anthropicは26日、米国政府の指示により公開を停止していた、最上位のAIモデル「Claude Mythos 5」(ミュトス5)について、重要インフラの運用と防御を行なう米国組織に限定し、再展開可能であるとの通知を受け取ったと発表した。', '2026-06-27T14:13:48.843+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwfxkfo0003xsv3ny68ueyf', 'cmqwfwoqj0001xsv3l851r09m', 'OpenAI「GPT-5.6」発表　最上位「Sol」など3モデルを政府要請で段階提供', 'https://www.watch.impress.co.jp/docs/news/2120569.html', '2026-06-27T01:57:44.000+00:00', 'https://www.watch.impress.co.jp/img/ipw/list/2120/569/open1.jpg', 'OpenAIは26日(米国時間)、最新のAIモデル「GPT-5.6」を発表した。フラッグシップモデルの「Sol」、日常業務向けのバランスの取れたモデル「Terra」、高速で価格を抑えた「Luna」の3モデルとなり、今後数週間で段階的に公開していく。', '2026-06-27T14:13:48.852+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwfxkfw0004xsv3bbbljle9', 'cmqwfwoqj0001xsv3l851r09m', 'G-SHOCK、上品な“漆黒”でみせる2100シリーズ4機種', 'https://www.watch.impress.co.jp/docs/news/2119763.html', '2026-06-27T01:00:00.000+00:00', 'https://www.watch.impress.co.jp/img/ipw/list/2119/763/pic-003.jpg', 'カシオ計算機は、G-SHOCKの新作として、2100シリーズを上品なブラックでまとめたカラーバリエーション「LUXE BLACK」シリーズ4機種を発売した。価格は20,900円～32,450円。', '2026-06-27T14:13:48.860+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwfxkg50005xsv384mjjz7p', 'cmqwfwoqj0001xsv3l851r09m', '小さくなって“着け続ける”価値が増した　Oura Ring 5の真価【ミニレビュー】', 'https://www.watch.impress.co.jp/docs/review/minireview/2119742.html', '2026-06-27T00:20:00.000+00:00', 'https://www.watch.impress.co.jp/img/ipw/list/2119/742/0.jpg', 'Ouraのスマートリング新モデル「Oura Ring 5」が登場しました。Ring 4と比べて本体を小型化し、より着け続けやすいデザインにしたことが主な変更点です。', '2026-06-27T14:13:48.869+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwfxkgd0006xsv3j5m76fgz', 'cmqwfwoqj0001xsv3l851r09m', 'さよならドクターイエロー', 'https://www.watch.impress.co.jp/docs/topic/watchplus/2120353.html', '2026-06-27T00:00:00.000+00:00', 'https://www.watch.impress.co.jp/img/ipw/list/2120/353/jrw07.jpg', 'Impress Watchニュースレターに掲載した記事です。ニュースレターは無料で、毎週編集部員が会員向けのコラムなどをお送りしています。登録はこちらから。', '2026-06-27T14:13:48.877+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwfxkgm0007xsv3nhy1alzp', 'cmqwfwoqj0001xsv3l851r09m', 'ミャクミャクモニュメントを道頓堀・かに道楽前に設置', 'https://www.watch.impress.co.jp/docs/news/2120488.html', '2026-06-26T23:30:00.000+00:00', 'https://www.watch.impress.co.jp/img/ipw/list/2120/488/osaka_00.jpg', '大阪府は、2025年に開催された大阪・関西万博の公式キャラクター「ミャクミャク」のモニュメントを、道頓堀商店街 かに道楽本店前に設置すると発表した。設置期間は7月6日から8月31日。', '2026-06-27T14:13:48.886+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwfxkgu0008xsv34f7hii7d', 'cmqwfwoqj0001xsv3l851r09m', 'Bluesky、ユーザー数が4500万人を突破', 'https://www.watch.impress.co.jp/docs/news/2120504.html', '2026-06-26T09:50:16.000+00:00', 'https://www.watch.impress.co.jp/img/ipw/list/2120/504/bs01.jpg', '分散型SNSのBlueskyは、世界のユーザー数が4,500万人を突破したことを明らかにした。', '2026-06-27T14:13:48.894+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwfxkh20009xsv3ou2zps49', 'cmqwfwoqj0001xsv3l851r09m', 'JR各社、新幹線に防火毛布・バケツ配備　モバイルバッテリ発火対策', 'https://www.watch.impress.co.jp/docs/news/2120470.html', '2026-06-26T09:00:00.000+00:00', 'https://www.watch.impress.co.jp/img/ipw/list/2120/470/01.jpg', 'JRグループは、新幹線車内でモバイルバッテリーの発煙・発火などの事案が発生していることを踏まえ、防火補助用品を新たに配備すると発表した。JR北海道、JR東日本、JR東海、JR西日本、JR九州の5社で実施する。', '2026-06-27T14:13:48.902+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwfxkha000axsv3sq1znh3a', 'cmqwfwoqj0001xsv3l851r09m', '東急大井町高架下に歩行者通路　大井町トラックスと商店街を結ぶ', 'https://www.watch.impress.co.jp/docs/news/2120463.html', '2026-06-26T08:31:59.000+00:00', 'https://www.watch.impress.co.jp/img/ipw/list/2120/463/oimachi_01.jpg', '大井町駅周辺において、3月に開業した複合施設「OIMACHI TRACKS(大井町トラックス)」と、東急大井町線高架下の商店街やイトーヨーカドーなどがある地区南側とを結ぶ東急大井町線高架下の歩行者専用通路が、6月30日に開通する。UR都市機構が発表した。', '2026-06-27T14:13:48.910+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwfxkhj000bxsv3flw7phy5', 'cmqwfwoqj0001xsv3l851r09m', '横浜市瀬谷区に「イオンスタイル三ツ境」 7月開業　三ツ境駅徒歩4分', 'https://www.watch.impress.co.jp/docs/news/2120457.html', '2026-06-26T08:14:49.000+00:00', 'https://www.watch.impress.co.jp/img/ipw/list/2120/457/1.jpg', 'イオンリテールは、神奈川県横浜市瀬谷区に「イオンスタイル三ツ境」を7月10日にオープンする。', '2026-06-27T14:13:48.919+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwfxkhr000cxsv3t2x31vmz', 'cmqwfwoqj0001xsv3l851r09m', 'Yahoo!ショッピングでも超PayPay祭　22%ポイント還元や50%オフ', 'https://www.watch.impress.co.jp/docs/news/2120423.html', '2026-06-26T06:57:31.000+00:00', 'https://www.watch.impress.co.jp/img/ipw/list/2120/423/00.jpg', 'LINEヤフーは、「Yahoo!ショッピング」において大型キャンペーン「超PayPay祭」を開始した。事前期間が6月26日～7月9日で、本開催は7月10日～12日の3日間。条件を満たすと最大22%がPayPayポイントで還元されるほか、生活に役立つ商品を厳選して値引きする「超目玉商品」などが展開される。', '2026-06-27T14:13:48.927+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwfxkhz000dxsv3y7ompuhx', 'cmqwfwoqj0001xsv3l851r09m', '空調服の撥水・UVカットマウンテンパーカー　男女兼用・4WAY', 'https://www.watch.impress.co.jp/docs/news/2120361.html', '2026-06-26T05:01:00.000+00:00', 'https://www.watch.impress.co.jp/img/ipw/list/2120/361/crossplus_00.jpg', 'アパレルメーカーのクロスプラスは、株式会社空調服とのコラボアイテム「空調服 晴雨兼用 UVマウンテンパーカー」を6月26日に発売した。価格は24,200円。ブランドは「CROSS FUNCTION(クロスファンクション)」。', '2026-06-27T14:13:48.936+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwfxki7000exsv3y430i29r', 'cmqwfwoqj0001xsv3l851r09m', 'ビックカメラ、携帯用“氷のう”発売　オリジナルブランド「ビックアイデア」', 'https://www.watch.impress.co.jp/docs/news/2120332.html', '2026-06-26T04:16:42.000+00:00', 'https://www.watch.impress.co.jp/img/ipw/list/2120/332/000.jpg', 'ビックカメラは、オリジナルブランド「ビックアイデア」の新製品として、携帯用氷のう「ICE BUDDIES」(アイスバディーズ)を6月下旬に発売する。全国のビックカメラグループ各店舗と通販サイトで順次取扱う。価格は1,980円。', '2026-06-27T14:13:48.943+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwfxkih000fxsv3vleyo9gc', 'cmqwfwoqj0001xsv3l851r09m', 'YouTubeショート、2倍速再生など新機能　“視聴禁止”設定も', 'https://www.watch.impress.co.jp/docs/news/2120301.html', '2026-06-26T03:31:25.000+00:00', 'https://www.watch.impress.co.jp/img/ipw/list/2120/301/01.jpg', 'YouTubeは26日、YouTube ショートのアップデートを発表した。2倍速再生や表示の改善など複数の新機能を順次展開し、より直感的に操作できるショート動画体験の構築を進める。', '2026-06-27T14:13:48.953+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwfxkip000gxsv3aej2qezn', 'cmqwfwoqj0001xsv3l851r09m', '青山、顔まで隠れる「着る虫よけ」', 'https://www.watch.impress.co.jp/docs/news/2120316.html', '2026-06-26T03:30:14.000+00:00', 'https://www.watch.impress.co.jp/img/ipw/list/2120/316/aoyama_00.jpg', '青山商事は、着るだけで虫を寄せにくくする「防虫メッシュアノラックプルオーバー」を6月26日に発売した。価格は3,289円。', '2026-06-27T14:13:48.961+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwfxkiy000hxsv37nu3pmfo', 'cmqwfwoqj0001xsv3l851r09m', 'フジHDとSBIグループが戦略業務提携へ　“感情経済圏”構築を目指す', 'https://www.watch.impress.co.jp/docs/news/2120302.html', '2026-06-26T03:15:12.000+00:00', 'https://www.watch.impress.co.jp/img/ipw/list/2120/302/sbifuji1.jpg', 'SBIグループとフジ・メディア・ホールディングスは、メディア・コンテンツ領域における資本戦略的業務提携に向けた協議・検討を開始した。新たな“感情経済圏”の構築を目指すとしている。', '2026-06-27T14:13:48.970+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwfxkj7000ixsv3a9ri69jg', 'cmqwfwoqj0001xsv3l851r09m', 'Notionメール、9月に終了　「受信箱」利用減でエージェントに注力', 'https://www.watch.impress.co.jp/docs/news/2120293.html', '2026-06-26T03:12:37.000+00:00', 'https://www.watch.impress.co.jp/img/ipw/list/2120/293/1.jpg', 'Notionは、9月22日に「Notionメール」の提供を終了する。対象はすべてのNotionプランで、iOS、デスクトップ、Web向けのNotionメールアプリが廃止される予定。終了前の26年6月25日から、Notionメール専用データのエクスポートをアプリやWebで受け付ける。', '2026-06-27T14:13:48.979+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwfxkjf000jxsv3ql5r43re', 'cmqwfwoqj0001xsv3l851r09m', '欧州委、AWSやAzureをデジタル規制対象に　DMAをクラウド適用', 'https://www.watch.impress.co.jp/docs/news/2120254.html', '2026-06-26T02:17:14.000+00:00', 'https://www.watch.impress.co.jp/img/ipw/list/2120/254/dma1.jpg', '欧州委員会は25日(現地時間)、AmazonとMicrosoftに対し、それぞれのクラウドコンピューティングサービスである「Amazon Web Services(AWS)」と「Microsoft Azure(Azure)」について、デジタル市場法(DMA)に基づくゲートキーパーとして指定すべきであるとの暫定見解を通知した。', '2026-06-27T14:13:48.987+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwfxkjo000kxsv3zdg5w3pi', 'cmqwfwoqj0001xsv3l851r09m', 'G-SHOCK・BABY-G、カモフラ柄を大胆に取り入れた11モデルが登場', 'https://www.watch.impress.co.jp/docs/news/2119368.html', '2026-06-26T01:34:55.000+00:00', 'https://www.watch.impress.co.jp/img/ipw/list/2119/368/gc00.jpg', 'カシオ計算機は、G-SHOCKとBABY-Gの新作として、カモフラージュ柄をベースにゴールドカラーやビビッドなカラーが特徴のカラーバリエーション「BOLD CAMO」シリーズ11機種を発売した。いずれも電池駆動のクオーツ式腕時計で、価格は15,400円～35,200円。', '2026-06-27T14:13:48.997+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwfxkjx000lxsv3lvqeg5j3', 'cmqwfwoqj0001xsv3l851r09m', '【鈴木淳也のPay Attention】「コンビニ」の限界を超える　ローソンの地域・オフィス・ミニスーパー新戦略', 'https://www.watch.impress.co.jp/docs/series/suzukij/2120198.html', '2026-06-26T00:03:19.000+00:00', 'https://www.watch.impress.co.jp/img/ipw/list/2120/198/j01.jpg', '最近、コンビニチェーン「ローソン」の動きが面白い。同社では現在さまざまな出店フォーマットの模索を行なっており、加えて親会社の1つであるKDDIと共同で「au経済圏」のさらなる拡大を進めている段階だ。', '2026-06-27T14:13:49.005+00:00');
