INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwjb31o001ot8v39h2ayho8', 'cmqwjb0ad001nt8v3hp5o0h4q', 'スマホ写真の「なんか違う」、光のせいかも。撮る前に整える3枚のフィルターがいい感じ', 'https://www.roomie.jp/2026/06/1811216/', '2026-06-27T14:45:23.000+00:00', 'https://media.loom-app.com/roomie/dist/images/2026/06/cinemalightfilter5.jpg?w=1200', '※こちらは「かいサポ（お買いものサポーターチーム）」が編集・執筆した記事です。 Photographed by miraarc スマホの写真は年々きれいになっているのに、撮った後でなんとなく釈然としないことがあります。肉眼で感じたあの光の柔らかさ、空気の質感——それが写真に残らない歯がゆさは、多くの人が経験していることではないでしょうか。 その原因は技術でも腕でもなく、光そのものにありそうです。', '2026-06-27T15:48:18.348+00:00');
