INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwjb38z002mt8v3jnakpxjx', 'cmqwjb0ad001nt8v3hp5o0h4q', 'ブラックライトをかざすと裏蓋に赤い蛇が現れる腕時計、ロマンが過ぎるんだよなぁ', 'https://www.roomie.jp/2026/06/1809111/', '2026-06-26T04:45:00.000+00:00', 'https://media.loom-app.com/roomie/dist/images/2026/06/vixa3.jpg?w=1200', '※こちらは「かいサポ（お買いものサポーターチーム）」が編集・執筆した記事です。 Photographed by ANPD_VISION レオナルド・ダ・ヴィンチが遺したもの。モナ・リザの微笑み、暗号めいたスケッチ、映画で描かれた数々のミステリーを思い浮かべる人もいるでしょう。 そんな天才の発想力を、手首の上で感じられそうな一本があります。 1935年に設立されたドイツの老舗時計ブランド「VIXA」', '2026-06-27T15:48:18.611+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwjb397002nt8v3nwcrq4yc', 'cmqwjb0ad001nt8v3hp5o0h4q', '燕三条の職人が削り出した19gの名刺入れ。贈った相手にずっと使ってもらえる一台', 'https://www.roomie.jp/2026/06/1809048/', '2026-06-26T02:45:49.000+00:00', 'https://media.loom-app.com/roomie/dist/images/2026/06/tsubanecase2.png?w=1200', '※こちらは「かいサポ（お買いものサポーターチーム）」が編集・執筆した記事です。 Photographed by TSUBANE-PROJECT 贈り物選びは、いつも悩ましいものです。実用的すぎると味気なく、凝りすぎると好みが分かれる。ビジネスの相手や大切な人に「ちょうどいい上質さ」を見つけるのは、意外と骨が折れますよね。 そんなとき候補にしたいのが、燕三条の職人が手がける純チタン名刺入れ「TSUB', '2026-06-27T15:48:18.619+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwjb39e002ot8v3ih0fmm6a', 'cmqwjb0ad001nt8v3hp5o0h4q', 'PIZZA PARTYの1日は幸せ気分で終わったのでした【こぐれひでこの｢ごはん日記｣】', 'https://www.roomie.jp/2026/06/1806214/', '2026-06-26T02:30:16.000+00:00', 'https://media.loom-app.com/roomie/dist/images/2026/06/260614_kogureh_10-1.jpeg?w=1200', '6月14日 朝ごはん プロテイン、ヨーグルト+梅ジャム。 昼ごはん 今日は鎌倉の武内宅のお庭でPIZZA PARTY。「お邪魔しま～す！」とみんなワクワク。 緑に包まれたお庭は、極上の気持ちよさ。 迎えてくれたのは、雄平さんとしょうこさんのご夫妻。 ピザ窯は雄平さんの手造り。ロボットみたいでとても可愛い。 一番手はサルシッチャ＆トマトのPIZZA（サルシッチャは西川さん持参）。耳がしっかり立ち上が', '2026-06-27T15:48:18.626+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwjb39l002pt8v3pw4grhct', 'cmqwjb0ad001nt8v3hp5o0h4q', 'お気に入りの豆を、ゆっくり飲みきれる。コーヒーには真空キャニスターが欠かせないね', 'https://www.roomie.jp/2026/06/1808600/', '2026-06-26T01:45:32.000+00:00', 'https://media.loom-app.com/roomie/dist/images/2026/06/image_002_862f3fe6.jpg?w=1200', '※こちらは「かいサポ（お買いものサポーターチーム）」が編集・執筆した記事です。 Photographed by junior お気に入りの豆ほど、開封後は「早く飲み切らなきゃ」と気が急いてしまうもの。でも本当は、最後の一杯までゆっくり味わいたいですよね。 そんなときに見つけたのが、CoSTORYの「SHELBRU CANISTER STAINLESS」。ボタンひとつで真空にして鮮度を守ってくれる、', '2026-06-27T15:48:18.633+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwjb39t002qt8v31c3gq8wz', 'cmqwjb0ad001nt8v3hp5o0h4q', '51%オフも！Amazonタイムセールで「クーラーボックス」や「ショルダーバッグ」が今ならお買い得ですよ', 'https://www.roomie.jp/2026/06/1809729/', '2026-06-26T01:30:34.000+00:00', 'https://media.loom-app.com/roomie/dist/images/2026/06/438b9e9e43b5e16deb029db23f32a625-19.png?w=1200', 'Amazon（アマゾン）で毎日開催されているAmazonタイムセール、今日2026年6月26日は「クーラーボックス」や「ショルダーバッグ」ほか、今すぐ欲しい人気のアイテムがお得に多数登場しています。 なお、以下の表示価格は2026年6月26日10時30分現在のもの。変更や売り切れの可能性もありますので、それぞれ販売ページでご確認ください（サイズやカラー選択も可能ですが、一部セール対象外のサイズ・カ', '2026-06-27T15:48:18.641+00:00');
INSERT INTO "Article" ("id", "siteId", "title", "url", "publishedAt", "thumbnailUrl", "excerpt", "fetchedAt") VALUES ('cmqwjb3a1002rt8v36ev7ygov', 'cmqwjb0ad001nt8v3hp5o0h4q', '指先サイズで録音→文字起こし→要約こなす。AnkerのAIボイレコが容量アップだ', 'https://www.roomie.jp/2026/06/1807387/', '2026-06-26T01:15:20.000+00:00', 'https://media.loom-app.com/roomie/dist/images/2026/06/4-1.png?w=1200', '※こちらは「かいサポ（お買いものサポーターチーム）」が編集・執筆した記事です。  会議が終わったあと、録音データを聞き返しながら文字起こしして議事録を作る。そんな作業が当たり前だった時代は終わりを迎えつつあります。 録音はレコーダー、文字起こし＆要約は人間。長らく続いてきたその分業体制は、Anker（アンカー）の最新・極小ウェアラブルAIボイスレコーダー「Soundcore Work（6', '2026-06-27T15:48:18.649+00:00');
